&amp;quot;:0,&amp;quot;hclr_color&amp;quot;:&amp;quot;#d4edbc&amp;quot;},&amp;quot;ts_fgc2&amp;quot;:{&amp;quot;clr_type&amp;quot;:0,&amp;quot;hclr_color&amp;quot;:&amp;quot;#11734b&amp;quot;},&amp;quot;ts_bd_i&amp;quot;:false,&amp;quot;ts_fs_i&amp;quot;:false,&amp;quot;ts_ff_i&amp;quot;:false,&amp;quot;ts_it_i&amp;quot;:false,&amp;quot;ts_sc_i&amp;quot;:false,&amp;quot;ts_st_i&amp;quot;:false,&amp;quot;ts_un_i&amp;quot;:false,&amp;quot;ts_va_i&amp;quot;:false,&amp;quot;ts_bgc2_i&amp;quot;:false,&amp;quot;ts_fgc2_i&amp;quot;:false},&amp;quot;di-cv&amp;quot;:{&amp;quot;dicv_v&amp;quot;:0,&amp;quot;dicv_ft&amp;quot;:0}},{&amp;quot;di-id&amp;quot;:&amp;quot;dropdownItem.bdlh9b3dju7d&amp;quot;,&amp;quot;di-v&amp;quot;:&amp;quot;Hour&amp;quot;,&amp;quot;di-dv&amp;quot;:&amp;quot;Hour&amp;quot;,&amp;quot;di-ts&amp;quot;:{&amp;quot;ts_bd&amp;quot;:false,&amp;quot;ts_fs&amp;quot;:11,&amp;quot;ts_ff&amp;quot;:&amp;quot;Arial&amp;quot;,&amp;quot;ts_it&amp;quot;:false,&amp;quot;ts_sc&amp;quot;:false,&amp;quot;ts_st&amp;quot;:false,&amp;quot;ts_tw&amp;quot;:400,&amp;quot;ts_un&amp;quot;:false,&amp;quot;ts_va&amp;quot;:&amp;quot;nor&amp;quot;,&amp;quot;ts_bgc2&amp;quot;:{&amp;quot;clr_type&amp;quot;:0,&amp;quot;hclr_color&amp;quot;:&amp;quot;#c6dbe1&amp;quot;},&amp;quot;ts_fgc2&amp;quot;:{&amp;quot;clr_type&amp;quot;:0,&amp;quot;hclr_color&amp;quot;:&amp;quot;#215a6c&amp;quot;},&amp;quot;ts_bd_i&amp;quot;:false,&amp;quot;ts_fs_i&amp;quot;:false,&amp;quot;ts_ff_i&amp;quot;:false,&amp;quot;ts_it_i&amp;quot;:false,&amp;quot;ts_sc_i&amp;quot;:false,&amp;quot;ts_st_i&amp;quot;:false,&amp;quot;ts_un_i&amp;quot;:false,&amp;quot;ts_va_i&amp;quot;:false,&amp;quot;ts_bgc2_i&amp;quot;:false,&amp;quot;ts_fgc2_i&amp;quot;:false},&amp;quot;di-cv&amp;quot;:{&amp;quot;dicv_v&amp;quot;:0,&amp;quot;dicv_ft&amp;quot;:0}}]}},&amp;quot;ddefe-t&amp;quot;:&amp;quot;SELECT STATUS&amp;quot;,&amp;quot;type&amp;quot;:&amp;quot;dropdown&amp;quot;}&quot;&gt;ear&lt;/span&gt;. Aurora’s pay ranges are determined by role, level, and location. Within the range, the successful candidate’s starting base pay will be determined based on factors including job-related skills, experience, qualifications, relevant education or training, and market conditions. These ranges may be modified in the future. The successful candidate will also be eligible for an annual bonus, equity compensation, and benefits.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;&amp;nbsp;#LI-Entry-Level&lt;/span&gt;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;strong&gt;Working at Aurora&lt;/strong&gt;&lt;strong&gt;&lt;br&gt;&lt;/strong&gt;At Aurora, we bring together extraordinarily talented and experienced people united by the strength of our values. We operate with integrity, set outrageous goals, and build a culture where we win together — all without any jerks.&lt;/p&gt;
&lt;p&gt;We believe in-person work increases collaboration, empathy and our ability to lead effectively. As a result, we operate in a hybrid work environment where Aurorans are in office at least 3 days per week.&lt;/p&gt;
&lt;p&gt;Our&lt;a href=&quot;https://aurora.tech/careers&quot;&gt; Careers page&lt;/a&gt; provides insight into what it is like to work at Aurora, and you can find all the latest updates in our &lt;a href=&quot;https://aurora.tech/newsroom&quot;&gt;Newsroom&lt;/a&gt;.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Our commitment to safety&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;At the core of everything we do is our commitment to safety. Building best-in-class self-driving technology will take time, and we believe that each employee at Aurora has a role in contributing to safety, every step of the way. Aurora expects commitment to our safety policies from every employee, and seeks candidates who take an active responsibility, can contribute to building an atmosphere of trust, and invest in the organization’s long-term success by prioritizing working safely, no matter what.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Our commitment to inclusion&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Aurora considers candidates without regard to their race, color, religion, national origin, age, sex, gender, gender identity, gender expression, sexual orientation, marital status, pregnancy status, parent or caregiver status, ancestry, political affiliation, veteran and/or military status, physical or mental disability, or any other status protected by federal or state law. Aurora considers qualified applicants with criminal histories, consistent with applicable federal, state, and local law. We are also committed to providing reasonable accommodations for qualified individuals with disabilities and disabled veterans in our job application procedures. If you need assistance or an accommodation due to a disability, you may contact us at &lt;a href=&quot;mailto:careersiteaccommodations@aurora.tech&quot;&gt;careersiteaccommodations@aurora.tech&lt;/a&gt;.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;For California applicants, information collected and processed as part of your application and any job applications you choose to submit is subject to Aurora’s California Employment Privacy Policy.&lt;/em&gt;&lt;/p&gt;&lt;/div&gt;

&lt;div class=&quot;content-intro&quot;&gt;&lt;h3&gt;&lt;strong&gt;Who We Are&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;Verkada is transforming how organizations protect their people and places with an integrated, AI-powered platform. A leader in cloud physical security, Verkada helps organizations strengthen safety and efficiency through one connected software platform that includes solutions for video security, access control, air quality sensors, alarms, intercoms, and visitor management.&lt;br&gt;&lt;br&gt;Over 30,000 organizations worldwide, including more than 100+ companies in the Fortune 500, trust Verkada as their physical security layer for easier management, intelligent control, and scalable deployments. Founded in 2016, Verkada has expanded rapidly with 15 offices and 2,200+ full-time employees.&lt;/p&gt;&lt;/div&gt;&lt;h3&gt;About the Role&amp;nbsp;&lt;/h3&gt;
&lt;p&gt;Verkada is seeking an Enterprise Field Solution Engineer in the Central US Region with expert experience in Cloud Security, IoT Systems, Networking, Linux systems, Security Surveillance and Access Control. This individual will partner directly with their territory account executives to expand the Verkada footprint upmarket into Fortune 500 companies.&amp;nbsp; Responsibilities include directly interfacing with customers/partners throughout the sales process, overcoming technical objections, assisting customers in designing deployments with Verkada Products and providing technical assistance to territory account reps. The ideal candidate will be highly motivated, able to learn quickly and work independently while making impactful results for the company remotely.&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;What You&#39;ll Do&lt;/strong&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Technical Leader: &lt;/strong&gt;Be the subject matter authority on the full Verkada suite of products and offerings and articulate the value added benefits to customers throughout the sales process.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Objection Handler: &lt;/strong&gt;Overcome objections and defuse landmines while securing the technical win for Verkada.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Evangelist: &lt;/strong&gt;Effectively present the Verkada solution to all levels of customer, from C-level executives to loss prevention managers and directors of IT. Be a Product Technical Evangelist in training/educating partners, customers, and internal employees on the latest Verkada product offerings.&lt;/li&gt;
&lt;li&gt;This role requires regular travel, estimated&amp;nbsp;to be more than 50%&amp;nbsp;of the time, including both domestic and international destinations as needed. The successful candidate must be comfortable with frequent travel to support business operations, customer and partner&amp;nbsp;engagements&amp;nbsp;and&amp;nbsp;team collaboration.&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;&lt;strong&gt;What You Bring&lt;/strong&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;3+ years of experience as a Sales Engineer, with a proven track record of working with Fortune 500 companies.&lt;/li&gt;
&lt;li&gt;Outstanding written and verbal English communication skills in order to clearly and efficiently articulate technical matters with customers and partners.&lt;/li&gt;
&lt;li&gt;Bachelor&#39;s degree in relevant technical or security field&amp;nbsp; from an accredited university.&lt;/li&gt;
&lt;li&gt;Strong background in Networking: HTTPS, VLANs, TCP/IP, DNS, NAT devices, DHCP and Firewalls.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Bonus:&lt;/strong&gt;
&lt;ul&gt;
&lt;li&gt;Industry certifications: AWS, CCNA, CCDA, CCNP, MCSE, CEH, Security+, A+, Network+, Microsoft Azure, CISSP, CSP.&lt;/li&gt;
&lt;li&gt;Experience working with Active Directory, SAML/SCIM, API&#39;s, Python, and other coding languages is a plus.&lt;/li&gt;
&lt;li&gt;Startup experience.&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;&lt;strong&gt;US Employee Benefits&lt;/strong&gt;&lt;/h3&gt;
&lt;div&gt;
&lt;p&gt;Verkada is committed to fostering a workplace environment that prioritizes the holistic health and wellbeing of our employees and their families by offering comprehensive wellness perks, benefits, and resources. Our benefits and perks programs include, but are not limited to:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Healthcare programs that can be tailored to meet the personal health and financial well-being needs - Premiums are 100% covered for the employee under at least one plan and 80% for family premiums under all plans&lt;/li&gt;
&lt;li&gt;Nationwide medical, vision and dental coverage&lt;/li&gt;
&lt;li&gt;Health Saving Account (HSA) with annual employer contributions and Flexible Spending Account (FSA) with tax saving options&lt;/li&gt;
&lt;li&gt;Expanded mental health support&lt;/li&gt;
&lt;li&gt;Paid parental leave policy &amp;amp; fertility benefits&lt;/li&gt;
&lt;li&gt;Time off to relax and recharge through our paid holidays, firmwide extended holidays, flexible PTO and personal sick time&lt;/li&gt;
&lt;li&gt;Professional development stipend&lt;/li&gt;
&lt;li&gt;Wellness/fitness benefits&lt;/li&gt;
&lt;li&gt;Healthy lunches provided daily&lt;/li&gt;
&lt;li&gt;Commuter benefits&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;&lt;strong&gt;Additional Information&lt;/strong&gt;&lt;/h3&gt;
&lt;div class=&quot;docos-replyview-body docos-anchoredreplyview-body docos-replyview-body-emoji-reactable docos-replyview-body-emoji-reactable-background&quot;&gt;
&lt;ul&gt;
&lt;li&gt;You must be independently authorized to work in the U.S. We are unable to sponsor or take over sponsorship of an employment visa for this role, at this time.&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;&lt;div class=&quot;content-pay-transparency&quot;&gt;&lt;div class=&quot;pay-input&quot;&gt;&lt;div class=&quot;description&quot;&gt;&lt;p&gt;&lt;span style=&quot;font-size: 16px;&quot;&gt;&lt;strong&gt;&lt;span class=&quot;C9DxTc &quot;&gt;Annual Pay Range&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;At Verkada, we want to attract and retain the best employees, and compensate them in a way that appropriately and fairly values their individual contribution to the company. With that in mind, we carefully consider a number of factors to determine the appropriate starting pay for an employee, including their primary work location and an assessment of a candidate&#39;s skills and experience, as well as market demands and internal parity. A Verkada employee may be eligible for additional forms of compensation, depending on their role, including sales incentives, discretionary bonuses, and/or equity in the company in the form of restricted stock units (RSUs)&lt;/p&gt;
&lt;p&gt;Below is the annual on-target earnings (OTE) range for full-time employees for this position, comprised of base compensation and commissions (if applicable).&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;title&quot;&gt;Estimated Annual Pay Range&lt;/div&gt;&lt;div class=&quot;pay-range&quot;&gt;&lt;span&gt;$155,000&lt;/span&gt;&lt;span class=&quot;divider&quot;&gt;&amp;mdash;&lt;/span&gt;&lt;span&gt;$205,000 USD&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;h3&gt;&lt;strong&gt;Verkada Is An Equal Opportunity Employer&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;As an equal opportunity employer, Verkada is committed to providing employment opportunities to all individuals. All applicants for positions at Verkada will be treated without regard to race, color, ethnicity, religion, sex, gender, gender identity and expression, sexual orientation, national origin, disability, age, marital status, veteran status, pregnancy, or any other basis prohibited by applicable law.&lt;/p&gt;
&lt;p&gt;&lt;em&gt;Your application will be handled in accordance with our &lt;a href=&quot;https://www.verkada.com/privacy/candidate-privacy-policy&quot; target=&quot;_blank&quot; data-saferedirecturl=&quot;https://www.google.com/url?q=https://url.uk.m.mimecastprotect.com/s/E_spClO3Ac9pX43h9dXa8/&amp;amp;source=gmail&amp;amp;ust=1719327847319000&amp;amp;usg=AOvVaw10eB41dX5dzNP9yveIJLsf&quot;&gt;Candidate Privacy Policy&lt;/a&gt;.&amp;nbsp;&lt;/em&gt;&lt;/p&gt;&lt;/div&gt;

&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;&lt;strong&gt;Who we are&lt;/strong&gt;&lt;/p&gt;
&lt;p style=&quot;margin: 0px; padding: 0px;&quot;&gt;Aurora’s mission is to deliver the benefits of self-driving technology safely, quickly, and broadly.&lt;/p&gt;
&lt;p style=&quot;margin: 0px; padding: 0px;&quot;&gt;&lt;br&gt;&lt;a class=&quot;c-link c-link--focus-visible&quot; href=&quot;https://aurora.tech/aurora-driver&quot; target=&quot;_blank&quot; data-stringify-link=&quot;https://aurora.tech/aurora-driver&quot; data-sk=&quot;tooltip_parent&quot;&gt;The Aurora Driver&lt;/a&gt;&amp;nbsp;will create a new era in mobility and logistics, one that will bring a safer, more efficient, and more accessible future to everyone.&lt;/p&gt;
&lt;p style=&quot;margin: 0px; padding: 0px;&quot;&gt;&amp;nbsp;&lt;/p&gt;
&lt;p style=&quot;margin: 0px; padding: 0px;&quot;&gt;At Aurora, you will tackle massively complex problems alongside other passionate, intelligent individuals, growing as an expert while expanding your knowledge. For the latest news from Aurora, visit&amp;nbsp;&lt;a href=&quot;https://aurora.tech/&quot; target=&quot;_blank&quot;&gt;aurora.tech&lt;/a&gt;&amp;nbsp;or follow us on&amp;nbsp;&lt;a href=&quot;https://www.linkedin.com/company/auroradriver&quot; target=&quot;_blank&quot;&gt;LinkedIn&lt;/a&gt;.&lt;/p&gt;
&lt;p style=&quot;margin: 0px; padding: 0px;&quot;&gt;&amp;nbsp;&lt;/p&gt;&lt;/div&gt;&lt;p&gt;Aurora hires talented people with diverse backgrounds who are ready to help build a transportation ecosystem that will make our roads safer, get crucial goods where they need to go, and make mobility more efficient and accessible for all. We’re searching for a &lt;strong&gt;Software Engineer &lt;/strong&gt;to join &lt;strong&gt;Aurora’s Behavior Planning ML Platform team&lt;/strong&gt;.&amp;nbsp; Our team is responsible for building both the offline pipelines to train and evaluate models and the infrastructure to efficiently run these models onboard the vehicle. On the offboard side, we build and support&amp;nbsp; the large scale distributed pipelines that model developers rely on to source data at scale, train, and evaluate machine learning models. On the onboard side, we build and maintain the on-vehicle infrastructure required to deploy these models and run inference in a soft real-time system.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;In this role, you will&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Develop large scale pipelines for data extraction, model training and model evaluation&lt;/li&gt;
&lt;li&gt;Build and optimize onboard ML infrastructure used to deploy models and run inference onboard the vehicle&lt;/li&gt;
&lt;li&gt;Collaborate closely with motion planning, systems engineering, and other autonomy groups to define and develop critical ML workflow requirements.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Required Qualifications&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;BS or higher degree in Computer Science/Engineering or related fields. &amp;gt; 6 months of experience&lt;/li&gt;
&lt;li&gt;Strong programming skills in C++ or Python, ideally both&lt;/li&gt;
&lt;li&gt;Experience with machine learning frameworks (PyTorch or TensorFlow)&lt;/li&gt;
&lt;li&gt;Solid foundation in computer science fundamentals - especially operating system concepts including concurrency, memory management and process scheduling.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Desirable Qualifications&lt;/strong&gt; &lt;strong&gt;(this section is optional)&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Experience with GPU programming and Nvidia profiling tools - CUDA, NSight Systems, Nsight Compute&lt;/li&gt;
&lt;li&gt;Experience working in cloud compute (AWS, Azure, GCP) ideally with batch processing or other large-scale workflow management platforms.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Experience profiling and optimizing software on Linux&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;The base salary range for this position is $126,000 - $181,000 per year.&amp;nbsp; Aurora’s pay ranges are determined by role, level, and location. Within the range, the successful candidate’s starting base pay will be determined based on factors including job-related skills, experience, qualifications, relevant education or training, and market conditions. These ranges may be modified in the future. The successful candidate will also be eligible for an annual bonus, equity compensation, and benefits.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;#LI-JL261&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;#Mid-Senior&amp;nbsp;&lt;/span&gt;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;strong&gt;Working at Aurora&lt;/strong&gt;&lt;strong&gt;&lt;br&gt;&lt;/strong&gt;At Aurora, we bring together extraordinarily talented and experienced people united by the strength of our values. We operate with integrity, set outrageous goals, and build a culture where we win together — all without any jerks.&lt;/p&gt;
&lt;p&gt;We believe in-person work increases collaboration, empathy and our ability to lead effectively. As a result, we operate in a hybrid work environment where Aurorans are in office at least 3 days per week.&lt;/p&gt;
&lt;p&gt;Our&lt;a href=&quot;https://aurora.tech/careers&quot;&gt; Careers page&lt;/a&gt; provides insight into what it is like to work at Aurora, and you can find all the latest updates in our &lt;a href=&quot;https://aurora.tech/newsroom&quot;&gt;Newsroom&lt;/a&gt;.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Our commitment to safety&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;At the core of everything we do is our commitment to safety. Building best-in-class self-driving technology will take time, and we believe that each employee at Aurora has a role in contributing to safety, every step of the way. Aurora expects commitment to our safety policies from every employee, and seeks candidates who take an active responsibility, can contribute to building an atmosphere of trust, and invest in the organization’s long-term success by prioritizing working safely, no matter what.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Our commitment to inclusion&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Aurora considers candidates without regard to their race, color, religion, national origin, age, sex, gender, gender identity, gender expression, sexual orientation, marital status, pregnancy status, parent or caregiver status, ancestry, political affiliation, veteran and/or military status, physical or mental disability, or any other status protected by federal or state law. Aurora considers qualified applicants with criminal histories, consistent with applicable federal, state, and local law. We are also committed to providing reasonable accommodations for qualified individuals with disabilities and disabled veterans in our job application procedures. If you need assistance or an accommodation due to a disability, you may contact us at &lt;a href=&quot;mailto:careersiteaccommodations@aurora.tech&quot;&gt;careersiteaccommodations@aurora.tech&lt;/a&gt;.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;For California applicants, information collected and processed as part of your application and any job applications you choose to submit is subject to Aurora’s California Employment Privacy Policy.&lt;/em&gt;&lt;/p&gt;&lt;/div&gt;

&lt;p data-pm-slice=&quot;1 1 []&quot;&gt;CSQ127R66&lt;/p&gt;
&lt;p&gt;The AI Forward Deployed Engineering (AI FDE) team is a highly specialized customer-facing AI team at Databricks. We deliver professional services engagements to help our customers build and productionize first-of-its-kind AI applications. We work cross-functionally to shape long-term strategic priorities and initiatives alongside engineering, product, and developer relations, as well as support internal subject matter expert (SME) teams. We view our team as an ensemble: we look for individuals with strong, unique specializations to improve the overall strength of the team. This team is the right fit for you if you love working with customers, teammates, and fueling your curiosity for the latest trends in GenAI, LLMOps, and ML more broadly. This role can be remote.&lt;/p&gt;
&lt;p data-renderer-start-pos=&quot;2006&quot;&gt;&lt;strong data-renderer-mark=&quot;true&quot;&gt;The impact you will have:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Develop cutting-edge GenAI solutions, incorporating the latest techniques from our &lt;a href=&quot;https://www.databricks.com/research/mosaic&quot;&gt;Mosaic AI Research&lt;/a&gt; to solve customer problems.&lt;/li&gt;
&lt;li&gt;Own production rollouts of consumer and internally facing GenAI applications.&lt;/li&gt;
&lt;li&gt;Serve as a trusted technical advisor to customers across a variety of domains.&lt;/li&gt;
&lt;li&gt;Present at conferences such as &lt;a href=&quot;https://www.databricks.com/dataaisummit&quot;&gt;Data + AI Summit&lt;/a&gt;, recognized as a thought leader internally and externally.&lt;/li&gt;
&lt;li&gt;Collaborate cross-functionally with the product and engineering teams to influence priorities and shape the product roadmap.&lt;/li&gt;
&lt;/ul&gt;
&lt;p data-renderer-start-pos=&quot;2367&quot;&gt;&lt;strong data-renderer-mark=&quot;true&quot;&gt;What we look for:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Experience building GenAI applications, including RAG, multi-agent systems, Text2SQL, fine-tuning, etc., with tools such as HuggingFace, LangChain, and DSPy.&lt;/li&gt;
&lt;li&gt;Expertise in deploying production-grade GenAI applications, including evaluation and optimizations.&lt;/li&gt;
&lt;li&gt;Extensive years of hands-on industry data science experience, leveraging common machine learning and data science tools (i.e., pandas, scikit-learn, PyTorch, etc.).&lt;/li&gt;
&lt;li&gt;Experience building production-grade machine learning deployments on AWS, Azure, or GCP.&lt;/li&gt;
&lt;li&gt;Graduate degree in a quantitative discipline (Computer Science, Engineering, Statistics, Operations Research, etc.) or equivalent practical experience.&lt;/li&gt;
&lt;li&gt;Experience communicating and/or teaching technical concepts to non-technical and technical audiences alike.&lt;/li&gt;
&lt;li&gt;Passion for collaboration, life-long learning, and driving business value through AI.&lt;/li&gt;
&lt;li&gt;[Preferred] Experience using the Databricks Intelligence Platform and Apache Spark™ to process large-scale distributed datasets.&lt;/li&gt;
&lt;/ul&gt;&lt;div class=&quot;content-pay-transparency&quot;&gt;&lt;div class=&quot;pay-input&quot;&gt;&lt;div class=&quot;description&quot;&gt;&lt;p&gt;&amp;nbsp;&lt;/p&gt;
